
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_11_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_11", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.947673705560443e+00, -4.849845348544471e+00, -4.712719614430103e+00, -4.522658238259576e+00, -4.263399053888488e+00, -3.917592876748858e+00, -3.470316610583351e+00, -2.914500739476894e+00, -2.256612701216502e+00, -1.538287645023948e+00, -9.295770981117913e-01, -6.570046934480361e-01, -6.232400376255505e-01, -5.313104112063320e-01, -3.674360910238488e-01, -2.068013863877149e-01, -9.227446972424000e-02, -3.066440100553107e-02, -6.582792455405512e-03, -7.405416912739541e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


